import { useEffect, useState } from "react";
import { z } from "zod";
import { loadArea } from "./support";
export async function handled() { return await loadArea(); }
export function area(raw: string): number { return z.object({ area: z.number() }).parse(JSON.parse(raw)).area; }
export function label(status: "queued" | "running" | "done") { switch (status) { case "queued": return "Waiting"; case "running": return "Working"; case "done": return "Complete"; } }
export function Title({ name }: { name: string }) { const [count] = useState(0); useEffect(() => { document.title = name; }, [name]); return <span>{count}</span>; }
